// #05b294 (דרישות 6–9) / #0fc9cd (דרישה 3, 4) / #db2075 — блокировка и снятие блокировки через /admin, сообщение заблокированному.
// Кейсы: .qa/tests/admin-companies-users/ACU-13..ACU-18. План: .qa/e2e/specs/admin-companies-users.md.
// @data: МЕНЯЕТ ДАННЫЕ, поэтому идёт только в проекте `data` (один воркер). Блокируем ТОЛЬКО:
//   • компанию SIGNUP14A (id 0307264e-34e1-4b49-b559-bc8201f6eaa2, участник qa-add75b-34a884ea@…) — НЕ её тёзку SIGNUP14;
//   • пользователя INV14 (id 6ab697c0-be29-49e8-9291-64c4810ebe71, qa-inv14-62d78ddb@…) — компанию B НЕ трогаем.
// Снятие блокировки обязательно: в начале (чистое исходное состояние) и в afterAll (даже после падения) — через RPC platform_set_*:false.
// ВНИМАНИЕ: вход platform один (Supabase, ротация токена) — файл идёт строго по порядку (serial), одно окно platform на весь файл;
// запускать с --workers=1, не параллелить с другими тестами роли platform (admin-readonly.spec.ts, mobile-tables/admin-mobile.spec.ts).
// Секретов нет: сессии из .qa/auth/*.json (platform, inv14, signup14a, admin2, spoof14).
import * as fs from 'fs';
import { test, expect, Page, BrowserContext } from '@playwright/test';
import {
  TARGET, authPath, openRoleContext, openAdmin, companiesTable, usersTable, rowsOf, confirmDialog,
  unblockTargets, findSignup14aCompanyRow,
} from './helpers';

test.describe.configure({ mode: 'serial' });

const MSG_USER_TITLE = 'הגישה שלך למערכת חסומה';
const MSG_USER_BODY = /לבירור פנו למנהל החשבון בחברה או לצוות TAQO/;
const MSG_COMPANY_TITLE = 'חשבון החברה חסום';
const MSG_COMPANY_BODY = /לבירור פנו לצוות TAQO/;
const SETUP_TITLE = 'הקמת חשבון חברה';

let platformCtx: BrowserContext;
let platform: Page;

const nav = (p: Page) => p.getByRole('navigation', { name: 'ניווט ראשי' });

/** Обычный вход: меню на месте, сообщения о блокировке нет, мастер /setup не открыт. */
async function expectNormalApp(p: Page) {
  await expect(nav(p)).toBeVisible();
  await expect(p.getByText(MSG_USER_TITLE, { exact: true })).toHaveCount(0);
  await expect(p.getByText(MSG_COMPANY_TITLE, { exact: true })).toHaveCount(0);
  await expect(p).not.toHaveURL(/\/setup/);
  await expect(p.getByText(SETUP_TITLE, { exact: true })).toHaveCount(0);
}

test.beforeAll(async ({ browser }, testInfo) => {
  platformCtx = await openRoleContext(browser, testInfo, 'platform');
  platform = await platformCtx.newPage();
  await unblockTargets(platform); // чистое исходное состояние (в т.ч. после прерванного прогона)
});
test.afterAll(async () => {
  try {
    if (platform) await unblockTargets(platform); // обязательное снятие блокировок
  } finally {
    await platformCtx?.close();
  }
});

test.describe('חסימת משתמש (INV14) דרך מסך הניהול', () => {
  let userCtx: BrowserContext;
  let inv14: Page;

  test.beforeAll(async ({ browser }, testInfo) => {
    userCtx = await openRoleContext(browser, testInfo, 'inv14');
    inv14 = await userCtx.newPage();
    await inv14.goto('/'); // сессия открыта ДО блокировки (проверка «уже вошёл»)
    await expectNormalApp(inv14);
  });
  test.afterAll(async () => {
    await userCtx?.close();
  });

  test('חסימת משתמש: אישור → תג "חסום", כפתור "ביטול חסימה", החברה נשארת פעילה #05b294 #0fc9cd @desktop @data', async () => {
    // ACU-13 — דרישות 6, 8, 9 (#05b294); דרישה 3 (#0fc9cd)
    await openAdmin(platform);
    const row = rowsOf(usersTable(platform)).filter({ hasText: TARGET.userEmail });
    await expect(row, 'ברשימה חייב להיות בדיוק משתמש INV14 אחד').toHaveCount(1);
    await row.getByRole('button', { name: 'חסימה', exact: true }).click();
    await confirmDialog(platform, 'חסימה');
    await expect(row.getByText('חסום', { exact: true })).toBeVisible();
    await expect(row.getByRole('button', { name: 'ביטול חסימה', exact: true })).toBeVisible();
    await expect(row.getByRole('button', { name: 'חסימה', exact: true })).toHaveCount(0);
    // החברה B לא נחסמה
    await expect(rowsOf(companiesTable(platform)).filter({ hasText: 'QA Company B' }).first().getByText('פעילה', { exact: true })).toBeVisible();
    // המצב נשמר בשרת
    await platform.reload();
    await expect(rowsOf(usersTable(platform)).filter({ hasText: TARGET.userEmail }).getByText('חסום', { exact: true })).toBeVisible();
  });

  test('משתמש חסום (סשן פתוח) אחרי רענון: הודעת חסימה עם למי לפנות, בלי /setup #db2075 @desktop @data', async () => {
    // ACU-14 — AC1 / מה רצוי: «הודעה ברורה שהגישה חסומה ולמי לפנות», לא מועבר ל-/setup
    await inv14.reload();
    await expect(inv14.getByText(MSG_USER_TITLE, { exact: true })).toBeVisible();
    await expect(inv14.getByText(MSG_USER_BODY)).toBeVisible();
    await expect(inv14).not.toHaveURL(/\/setup/);
    await expect(inv14.getByText(SETUP_TITLE, { exact: true })).toHaveCount(0);
    await expect(inv14.getByRole('button', { name: /יצירת חברה/ })).toHaveCount(0);
  });

  test('משתמש חסום: כניסה ישירה ל-/setup, /users, /onboarding לא מציגה את מסך הקמת החברה ואין לולאת הפניות #db2075 @desktop @data', async () => {
    // ACU-15 — комментарий jleprog39: прямой заход на /setup возвращает на главную с сообщением
    await inv14.goto('/setup');
    await expect(inv14).not.toHaveURL(/\/setup/);
    await expect(inv14.getByText(MSG_USER_TITLE, { exact: true })).toBeVisible();
    for (const route of ['/users', '/onboarding']) {
      await inv14.goto(route);
      await expect(nav(inv14)).toBeVisible();
      await expect(inv14, `${route}: без перехода на /setup`).not.toHaveURL(/\/setup/);
      await expect(inv14.getByText(SETUP_TITLE, { exact: true })).toHaveCount(0);
      await expect(inv14.getByRole('button', { name: /יצירת חברה/ })).toHaveCount(0);
    }
  });

  test('משתמש חסום לא פוגע בשאר המשתמשים בחברה שלו: מנהל חברה B נכנס כרגיל #db2075 @desktop @data', async ({ browser }, testInfo) => {
    // ACU-16 — Д1
    const ctx = await openRoleContext(browser, testInfo, 'admin2');
    try {
      const admin2 = await ctx.newPage();
      await admin2.goto('/');
      await expectNormalApp(admin2);
    } finally {
      await ctx.close();
    }
  });

  test('ביטול חסימת משתמש: אישור → תג "פעיל", והמשתמש נכנס כרגיל #05b294 #db2075 @desktop @data', async () => {
    // ACU-17 — AC3 #db2075; кнопка снятия есть (R-04 в документации молчит)
    await openAdmin(platform);
    const row = rowsOf(usersTable(platform)).filter({ hasText: TARGET.userEmail });
    await expect(row).toHaveCount(1);
    await row.getByRole('button', { name: 'ביטול חסימה', exact: true }).click();
    await confirmDialog(platform, 'ביטול חסימה');
    await expect(row.getByText('פעיל', { exact: true })).toBeVisible();
    await expect(row.getByRole('button', { name: 'חסימה', exact: true })).toBeVisible();
    await inv14.reload();
    await expectNormalApp(inv14);
  });
});

test.describe('חסימת חברה (SIGNUP14A) דרך מסך הניהול', () => {
  test.skip(!fs.existsSync(authPath('signup14a')), 'אין סשן signup14a (.qa/auth/signup14a.json) — אי אפשר לבדוק את ההודעה לחברה חסומה');
  let memberCtx: BrowserContext;
  let member: Page;

  test.beforeAll(async ({ browser }, testInfo) => {
    memberCtx = await openRoleContext(browser, testInfo, 'signup14a');
    member = await memberCtx.newPage();
    await member.goto('/');
    await expectNormalApp(member);
  });
  test.afterAll(async () => {
    await memberCtx?.close();
  });

  test('חסימת חברה: אישור → תג "חסומה", כפתור "ביטול חסימה" #05b294 #0fc9cd @desktop @data', async () => {
    // ACU-13 — דרישות 7, 8, 9 (#05b294); דרישה 4 (#0fc9cd). Строка: из двух «QA add75b» — та, где участник qa-add75b-34a884ea
    await openAdmin(platform);
    const row = await findSignup14aCompanyRow(platform);
    await row.getByRole('button', { name: 'חסימה', exact: true }).click();
    const dlg = platform.getByRole('dialog').or(platform.getByRole('alertdialog')).first();
    await expect(dlg.getByText(/לחסום את החברה/)).toBeVisible();
    await confirmDialog(platform, 'חסימה');
    await expect(row.getByText('חסומה', { exact: true })).toBeVisible();
    await expect(row.getByRole('button', { name: 'ביטול חסימה', exact: true })).toBeVisible();
  });

  test('משתמש בחברה חסומה (מנהל החשבון): "חשבון החברה חסום" עם למי לפנות, בלי /setup #db2075 @desktop @data', async () => {
    // ACU-18 — AC2: роль в компании не влияет (Т9)
    await member.reload();
    await expect(member.getByText(MSG_COMPANY_TITLE, { exact: true })).toBeVisible();
    await expect(member.getByText(MSG_COMPANY_BODY)).toBeVisible();
    await expect(member).not.toHaveURL(/\/setup/);
    await member.goto('/setup');
    await expect(member).not.toHaveURL(/\/setup/);
    await expect(member.getByText(MSG_COMPANY_TITLE, { exact: true })).toBeVisible();
    await expect(member.getByText(SETUP_TITLE, { exact: true })).toHaveCount(0);
  });

  test('ביטול חסימת חברה: אישור → תג "פעילה", והמשתמש נכנס כרגיל #05b294 #db2075 @desktop @data', async () => {
    // ACU-17 — AC3 #db2075 (компания)
    await openAdmin(platform);
    const row = await findSignup14aCompanyRow(platform);
    await row.getByRole('button', { name: 'ביטול חסימה', exact: true }).click();
    await confirmDialog(platform, 'ביטול חסימה');
    await expect(row.getByText('פעילה', { exact: true })).toBeVisible();
    await expect(row.getByRole('button', { name: 'חסימה', exact: true })).toBeVisible();
    await member.goto('/');
    await expectNormalApp(member);
  });
});
